INSERT INTO crm_wecom_callback_event (
    corp_id, event, change_type, user_id, external_userid, chat_id, tag_id, tag_type,
    update_detail, state, source, fail_reason, raw_xml, create_time
) VALUES (
    #{corpId}, #{event}, #{changeType}, #{userId}, #{externalUserid}, #{chatId}, #{tagId}, #{tagType},
    #{updateDetail}, #{state}, #{source}, #{failReason}, #{rawXml}, #{createTime}
)

mapper.select:
SELECT id, corp_id, event, change_type, user_id, external_userid, chat_id, tag_id, tag_type,
       update_detail, state, source, fail_reason, raw_xml, create_time, create_by, update_time, update_by, remark
FROM crm_wecom_callback_event


        AND corp_id = #{corpId}


        AND event = #{event}


        AND change_type = #{changeType}


        AND create_time >= #{params.beginTime}::timestamp


        AND create_time <= #{params.endTime}::timestamp


ORDER BY id DESC

SELECT event, COALESCE(change_type, '') AS change_type, COUNT(*) AS cnt
FROM crm_wecom_callback_event


        AND corp_id = #{corpId}


        AND event = #{event}


        AND change_type = #{changeType}


        AND create_time >= #{params.beginTime}::timestamp


        AND create_time <= #{params.endTime}::timestamp


GROUP BY event, change_type
ORDER BY event, change_type
